# Shopping Cart Component with Redux Toolkit

I'll build a complete shopping cart component with Redux Toolkit state management. Here's the full implementation:

## 1. Redux Store Configuration

```jsx
// store/store.js
import { configureStore } from '@reduxjs/toolkit';
import cartReducer from '../features/cartSlice';

export const store = configureStore({
  reducer: {
    cart: cartReducer,
  },
});

export default store;
```

## 2. Cart Feature Slice

```jsx
// features/cartSlice.js
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
  totalItems: 0,
  totalAmount: 0,
};

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem: (state, action) => {
      const item = action.payload;
      const existingItem = state.items.find(item => item.id === action.payload.id);

      if (existingItem) {
        existingItem.quantity += 1;
      } else {
        state.items.push({ ...item, quantity: 1 });
      }

      state.totalItems += 1;
      state.totalAmount += item.price;
    },

    removeItem: (state, action) => {
      const item = state.items.find(item => item.id === action.payload);

      if (item) {
        state.totalItems -= item.quantity;
        state.totalAmount -= item.price * item.quantity;
        state.items = state.items.filter(item => item.id !== action.payload);
      }
    },

    updateQuantity: (state, action) => {
      const { id, quantity } = action.payload;
      const item = state.items.find(item => item.id === id);

      if (item) {
        const oldQuantity = item.quantity;
        const quantityDifference = quantity - oldQuantity;

        item.quantity = quantity;
        state.totalItems += quantityDifference;
        state.totalAmount += (quantity - oldQuantity) * item.price;
      }
    },

    clearCart: (state) => {
      state.items = [];
      state.totalItems = 0;
      state.totalAmount = 0;
    },
  },
});

export const { addItem, removeItem, updateQuantity, clearCart } = cartSlice.actions;

export default cartSlice.reducer;
```

